// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(address(c), 200);
        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);
        assertTrue(alice.balance > 0);
    }
}
